independent.solution:
STAGES = 5
FAIL_STAGE = 3

def run(checkpointed):
    done, log, failed = 0, [], False
    while done < STAGES:
        start = done if checkpointed else 0
        try:
            for stage in range(start + 1, STAGES + 1):
                log.append(stage)
                if stage == FAIL_STAGE and not failed:
                    failed = True
                    raise RuntimeError('fail')
                done = stage
        except RuntimeError:
            continue
    return log

a, b = run(False), run(True)
print('without checkpoint:', a)
print('with checkpoint:', b)
print('extra work saved:', len(a) - len(b))
